"""Reviewable, parameterized Cypher used by the product (not generated by an LLM).

All mutation guards and their writes are in the same graph query. No Python mutex
is used to claim tasks: independent worker processes contend in FalkorDB.
"""

CREATE_INCIDENT = """
CREATE (i:Incident {id:$incident, title:$title, status:'open', created_at:$now})
CREATE (t:Task {id:$incident, status:'open', stage:'created', generation:0})
CREATE (i)-[:HAS_TASK]->(t)
MERGE (checkout:Service {name:'checkout'})
MERGE (inventory:Service {name:'inventory'})
MERGE (warehouse:Service {name:'warehouse'})
MERGE (checkout)-[:DEPENDS_ON]->(inventory)
MERGE (inventory)-[:DEPENDS_ON]->(warehouse)
CREATE (i)-[:AFFECTS]->(checkout)
MERGE (p:Procedure {name:'restore_inventory_route'})
ON CREATE SET p.precondition='inventory route differs from /stock', p.target='inventory'
MERGE (p)-[:APPLIES_TO]->(inventory)
RETURN properties(i)
"""

CLAIM = """
MATCH (i:Incident {id:$incident})-[:HAS_TASK]->(t:Task)
WHERE i.status='open' AND (t.status='open' OR
      (t.status='claimed' AND t.expires_at <= $now))
SET t.status='claimed', t.owner=$agent, t.token=$token,
    t.expires_at=$expires, t.generation=t.generation+1
MERGE (a:Agent {name:$agent})
CREATE (e:Episode {id:$event, kind:'claim', agent:$agent,
    content:'Task claimed', created_at:$now})
CREATE (i)-[:HAS_EPISODE]->(e)
CREATE (e)-[:BY]->(a)
RETURN properties(t)
"""

APPEND = """
MATCH (i:Incident {id:$incident})-[:HAS_TASK]->(t:Task)
WHERE t.status='claimed' AND t.token=$token AND t.expires_at > $now
CREATE (e:Episode {id:$event, kind:$kind, agent:t.owner,
    content:$content, payload:$payload, created_at:$now,
    verified:$verified, verified_action:$verified_action})
CREATE (i)-[:HAS_EPISODE]->(e)
RETURN properties(e)
"""

HYPOTHESIS = """
MATCH (i:Incident {id:$incident})-[:HAS_TASK]->(t:Task),
      (i)-[:HAS_EPISODE]->(e:Episode {id:$evidence})
WHERE t.status='claimed' AND t.token=$token AND t.expires_at > $now
CREATE (h:Hypothesis {id:$hypothesis, content:$content, current:true, valid_from:$now})
CREATE (i)-[:HAS_HYPOTHESIS]->(h)
CREATE (e)-[:SUPPORTS]->(h)
RETURN properties(h)
"""

SUPERSEDE = """
MATCH (i:Incident {id:$incident})-[:HAS_TASK]->(t:Task),
      (i)-[:HAS_HYPOTHESIS]->(old:Hypothesis {id:$old}),
      (i)-[:HAS_EPISODE]->(e:Episode {id:$evidence})
WHERE t.status='claimed' AND t.token=$token AND t.expires_at > $now AND old.current=true
SET old.current=false, old.valid_until=$now
CREATE (h:Hypothesis {id:$hypothesis, content:$content, current:true, valid_from:$now})
CREATE (i)-[:HAS_HYPOTHESIS]->(h)
CREATE (h)-[:SUPERSEDES]->(old)
CREATE (e)-[:CONTRADICTS]->(old)
CREATE (e)-[:SUPPORTS]->(h)
RETURN properties(h)
"""

HANDOFF = """
MATCH (i:Incident {id:$incident})-[:HAS_TASK]->(t:Task)
WHERE t.status='claimed' AND t.token=$token AND t.expires_at > $now
CREATE (e:Episode {id:$event, kind:'handoff', agent:t.owner,
    content:$content, created_at:$now})
CREATE (i)-[:HAS_EPISODE]->(e)
CREATE (e)-[:HANDS_OFF]->(t)
SET t.status='open', t.token='', t.owner='', t.expires_at=0
RETURN properties(e)
"""

START_ACTION = """
MATCH (i:Incident {id:$incident})-[:HAS_TASK]->(t:Task)
WHERE t.status='claimed' AND t.token=$token AND t.expires_at > $now
OPTIONAL MATCH (t)-[:HAS_ATTEMPT]->(previous:Action {tool:$tool, status:'failed'})
WITH i, t, count(previous) AS failed
WHERE failed=0
CREATE (a:Action {id:$action, tool:$tool, status:'running', agent:t.owner,
    started_at:$now, token:$token})
CREATE (t)-[:HAS_ATTEMPT]->(a)
SET t.status='running', t.stage='action_running'
RETURN properties(a)
"""

FINISH_ACTION = """
MATCH (i:Incident {id:$incident})-[:HAS_TASK]->(t:Task)-[:HAS_ATTEMPT]->(a:Action {id:$action})
WHERE t.status='running' AND t.token=$token AND a.status='running'
SET a.status=$status, a.result=$payload, a.finished_at=$now,
    t.status='claimed', t.stage='verifying', t.expires_at=$expires
CREATE (e:Episode {id:$event, kind:'action_result', agent:t.owner,
    content:$content, payload:$payload, created_at:$now})
CREATE (i)-[:HAS_EPISODE]->(e)
CREATE (a)-[:HAS_RESULT]->(e)
RETURN properties(a)
"""

RESOLVE = """
MATCH (i:Incident {id:$incident})-[:HAS_TASK]->(t:Task),
      (i)-[:HAS_EPISODE]->(e:Episode {id:$evidence})
WHERE t.status='claimed' AND t.token=$token AND t.expires_at > $now
      AND e.kind='health_verified' AND e.verified=true AND e.created_at >= $now-300
MATCH (t)-[:HAS_ATTEMPT]->(a:Action {id:e.verified_action})
WHERE a.finished_at <= e.created_at
SET i.status='resolved', i.resolved_at=$now, t.status='done', t.stage='resolved', t.token=''
CREATE (i)-[:RESOLVED_WITH]->(e)
WITH i,t,e
OPTIONAL MATCH (i)-[:HAS_HYPOTHESIS]->(h:Hypothesis)
SET h.current=false, h.valid_until=$now
WITH DISTINCT i
RETURN properties(i)
"""

DEPENDENCIES = """
MATCH (i:Incident {id:$incident})-[:AFFECTS]->(s:Service),
      p=(s)-[:DEPENDS_ON*1..4]->(dependency:Service)
RETURN [n IN nodes(p) | n.name] AS services, length(p) AS hops
ORDER BY hops
"""

FAILED_ACTIONS = """
MATCH (:Incident {id:$incident})-[:HAS_TASK]->(:Task)-[:HAS_ATTEMPT]->(a:Action)
WHERE a.status='failed'
RETURN properties(a)
ORDER BY a.started_at
"""

PROCEDURES = """
MATCH (:Incident {id:$incident})-[:AFFECTS]->(:Service)-[:DEPENDS_ON*1..4]->(s:Service)
MATCH (p:Procedure)-[:APPLIES_TO]->(s)
RETURN DISTINCT properties(p)
"""
